toolArgs.file_text:
.message-bubble {
    position: relative;
    padding: 8px 14px;
    border-radius: 6px;
    transition: background-color 0.15s;
}

.message-bubble:hover {
    background-color: rgba(255, 255, 255, 0.04);
}

.message-header {
    display: flex;
    align-items: baseline;
    gap: 8px;
    margin-bottom: 2px;
}

.author {
    font-weight: 700;
    font-size: 0.9rem;
    color: #e0e0e0;
}

.timestamp {
    font-size: 0.75rem;
    color: #757575;
}

.message-content {
    font-size: 0.9rem;
    color: #d0d0d0;
    line-height: 1.4;
    white-space: pre-wrap;
    word-break: break-word;
}

.reactions-row {
    display: flex;
    flex-wrap: wrap;
    gap: 4px;
    margin-top: 4px;
}

.reaction-badge {
    display: inline-flex;
    align-items: center;
    gap: 4px;
    background: rgba(255, 255, 255, 0.08);
    border: 1px solid rgba(255, 255, 255, 0.12);
    border-radius: 12px;
    padding: 2px 8px;
    font-size: 0.8rem;
    cursor: pointer;
    color: #d0d0d0;
    transition: background-color 0.15s;
}

.reaction-badge:hover {
    background: rgba(255, 255, 255, 0.15);
}

.reaction-count {
    font-size: 0.75rem;
}

.thread-link {
    background: none;
    border: none;
    color: #42a5f5;
    font-size: 0.8rem;
    cursor: pointer;
    padding: 2px 0;
    margin-top: 2px;
    font-weight: 600;
}

.thread-link:hover {
    text-decoration: underline;
}

.action-bar {
    position: absolute;
    top: -12px;
    right: 8px;
    display: flex;
    gap: 2px;
    background: #2a2a2a;
    border: 1px solid #444;
    border-radius: 6px;
    padding: 2px;
    box-shadow: 0 2px 8px rgba(0, 0, 0, 0.3);
}

.action-btn {
    background: transparent;
    border: none;
    cursor: pointer;
    padding: 4px 8px;
    border-radius: 4px;
    font-size: 1rem;
    line-height: 1;
    transition: background-color 0.15s;
}

.action-btn:hover {
    background-color: rgba(255, 255, 255, 0.1);
}

.react-wrapper {
    position: relative;
}

