@using sv_a0b3ea8c04ed4158af08aa6bb1561925.Services

<div class="thread-panel">
    <div class="thread-header">
        <h3>Thread</h3>
        <button class="close-btn" @onclick="OnClose" title="Close thread">✕</button>
    </div>

    @if (RootMessage is not null)
    {
        <div class="thread-root">
            <div class="root-author">@RootMessage.Author</div>
            <div class="root-content">@RootMessage.Content</div>
        </div>

        <div class="thread-divider">
            <span>@ThreadMessages.Count @(ThreadMessages.Count == 1 ? "reply" : "replies")</span>
        </div>

        <div class="thread-messages">
            @foreach (var msg in ThreadMessages)
            {
                <MessageBubble Message="msg" />
            }
        </div>

        <MessageInput Placeholder="Reply…" ButtonLabel="Reply" OnSubmit="OnReply" />
    }
</div>

@code {
    [Parameter] public Message? RootMessage { get; set; }
    [Parameter] public List<Message> ThreadMessages { get; set; } = [];
    [Parameter] public EventCallback<string> OnReply { get; set; }
    [Parameter] public EventCallback OnClose { get; set; }
}

.thread-panel {
    display: flex;
    flex-direction: column;
    height: 100%;
    background-color: #1e1e1e;
    border-left: 1px solid #333;
    overflow: hidden;
}

.thread-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 14px 16px;
    border-bottom: 1px solid #333;
}

.thread-header h3 {
    margin: 0;
    font-size: 1rem;
    font-weight: 700;
    color: #fff;
}

.close-btn {
    background: transparent;
    border: none;
    color: #9e9e9e;
    font-size: 1.1rem;
    cursor: pointer;
    padding: 4px 8px;
    border-radius: 4px;
    line-height: 1;
    transition: background-color 0.15s, color 0.15s;
}

.close-btn:hover {
    background-color: rgba(255, 255, 255, 0.1);
    color: #fff;
}

.thread-root {
    padding: 12px 16px;
    background-color: rgba(255, 255, 255, 0.04);
    border-bottom: 1px solid #333;
}

.root-author {
    font-weight: 700;
    font-size: 0.85rem;
    color: #e0e0e0;
    margin-bottom: 4px;
}

.root-content {
    font-size: 0.85rem;
    color: #bdbdbd;
    white-space: pre-wrap;
    word-break: break-word;
}

.thread-divider {
    display: flex;
    align-items: center;
    padding: 8px 16px;
    gap: 12px;
}

.thread-divider::before,
.thread-divider::after {
    content: '';
    flex: 1;
    height: 1px;
    background: #444;
}

.thread-divider span {
    font-size: 0.75rem;
    color: #757575;
    white-space: nowrap;
}

.thread-messages {
    flex: 1;
    overflow-y: auto;
    padding: 4px 0;
}

