+@page "/chat"
+@layout ChatLayout
+@rendermode InteractiveServer
+
+@using sv_a0b3ea8c04ed4158af08aa6bb1561925.Services
+@using sv_a0b3ea8c04ed4158af08aa6bb1561925.Components.Chat
+@inject IChatService ChatService
+
+<PageTitle>Chat</PageTitle>
+
+<div class="chat-layout">
+    <div class="chat-sidebar">
+        <ChannelSidebar Channels="_channels"
+                        SelectedChannelId="_selectedChannelId"
+                        OnChannelSelected="SelectChannel" />
+    </div>
+
+    <div class="chat-main @(_threadOpen ? "" : "expanded")">
+        @if (_selectedChannel is not null)
+        {
+            <div class="main-header">
+                <h2># @_selectedChannel.Name</h2>
+                <span class="header-desc">@_selectedChannel.Description</span>
+            </div>
+
+            <div class="message-scroll">
+                @if (_hasMoreMessages)
+                {
+                    <div class="load-more-area">
+                        <button class="load-more-btn" @onclick="LoadOlderMessages" disabled="@_loadingMore">
+                            @(_loadingMore ? "Loading…" : "Load older messages")
+                        </button>
+                    </div>
+                }
+
+                @foreach (var msg in _messages)
+                {
+                    <MessageBubble Message="msg"
+                                   ReplyCount="GetReplyCount(msg.Id)"
+                                   OnOpenThread="OpenThread"
+                                   OnReactionClicked="HandleReaction" />
+                }
+            </div>
+
+            <MessageInput Placeholder="@($"Message #{_selectedChannel.Name}")"
+                          OnSubmit="SendMessage" />
+        }
+        else
+        {
+            <div class="empty-state">
+                <p>Select a channel to start chatting</p>
+            </div>
+        }
+    </div>
+
+    @if (_threadOpen && _threadRootMessage is not null)
+    {
+        <div class="chat-thread">
+            <ThreadPanel RootMessage="_threadRootMessage"
+                         ThreadMessages="_threadMessages"
+                         OnReply="SendThreadReply"
+                         OnClose="CloseThread" />
+        </div>
+    }
+</div>
+
+@code {
+    private List<Channel> _channels = [];
+    private List<Message> _messages = [];
+    private List<Message> _threadMessages = [];
+    private Dictionary<int, int> _replyCounts = new();
+    private Channel? _selectedChannel;
+    private int _selectedChannelId;
+    private Message? _threadRootMessage;
+    private bool _threadOpen;
+    private bool _loadingMore;
+    private bool _hasMoreMessages = true;
+
+    private const int PageSize = 30;
+
+    protected override async Task OnInitializedAsync()
+    {
+        _channels = await ChatService.GetChannelsAsync();
+
+        if (_channels.Count > 0)
+        {
+            await SelectChannel(_channels[0].Id);
+        }
+    }
+
+    private async Task SelectChannel(int channelId)
+    {
+        _selectedChannelId = channelId;
+        _selectedChannel = _channels.FirstOrDefault(c => c.Id == channelId);
+        _messages = [];
+        _hasMoreMessages = true;
+        _replyCounts.Clear();
+
+        CloseThread();
+
+        var messages = await ChatService.GetMessagesAsync(channelId, 0, PageSize);
+        _messages = messages;
+        _hasMoreMessages = messages.Count >= PageSize;
+
+        await BuildReplyCounts();
+        await ChatService.MarkChannelReadAsync(channelId);
+
+        // Refresh channels to update unread counts
+        _channels = await ChatService.GetChannelsAsync();
+    }
+
+    private async Task LoadOlderMessages()
+    {
+        if (_loadingMore || _selectedChannel is null) return;
+
+        _loadingMore = true;
+
+        var older = await ChatService.GetMessagesAsync(_selectedChannel.Id, _messages.Count, PageSize);
+        if (older.Count < PageSize)
+        {
+            _hasMoreMessages = false;
+        }
+
+        _messages.InsertRange(0, older);
+        await BuildReplyCounts();
+
+        _loadingMore = false;
+    }
+
+    private async Task BuildReplyCounts()
+    {
+        // Build reply counts from messages that have ReplyToId set
+        _replyCounts.Clear();
+        foreach (var msg in _messages)
+        {
+            if (msg.ReplyToId is int rootId)
+            {
+                _replyCounts.TryGetValue(rootId, out var count);
+                _replyCounts[rootId] = count + 1;
+            }
+        }
+    }
+
+    private int GetReplyCount(int messageId) =>
+        _replyCounts.TryGetValue(messageId, out var count) ? count : 0;
+
+    private async Task SendMessage(string content)
+    {
+        if (_selectedChannel is null) return;
+
+        var sent = await ChatService.SendMessageAsync(_selectedChannel.Id, content, null);
+        _messages.Add(sent);
+    }
+
+    private async Task OpenThread(int rootMessageId)
+    {
+        _threadRootMessage = _messages.FirstOrDefault(m => m.Id == rootMessageId);
+        if (_threadRootMessage is null) return;
+
+        _threadMessages = await ChatService.GetThreadAsync(rootMessageId);
+        _threadOpen = true;
+    }
+
+    private void CloseThread()
+    {
+        _threadOpen = false;
+        _threadRootMessage = null;
+        _threadMessages = [];
+    }
+
+    private async Task SendThreadReply(string content)
+    {
+        if (_threadRootMessage is null || _selectedChannel is null) return;
+
+        var reply = await ChatService.SendMessageAsync(_selectedChannel.Id, content, _threadRootMessage.Id);
+        _threadMessages.Add(reply);
+
+        // Update reply count in the main view
+        _replyCounts.TryGetValue(_threadRootMessage.Id, out var count);
+        _replyCounts[_threadRootMessage.Id] = count + 1;
+    }
+
+    private async Task HandleReaction(MessageBubble.ReactionEvent e)
+    {
+        await ChatService.AddReactionAsync(e.MessageId, e.Emoji);
+
+        // Refresh the message list to show updated reactions
+        if (_selectedChannel is not null)
+        {
+            _messages = await ChatService.GetMessagesAsync(_selectedChannel.Id, 0, _messages.Count);
+        }
+    }
+}
+

toolArgs.file_text:
.chat-layout {
    display: flex;
    height: 100vh;
    width: 100%;
    overflow: hidden;
    background-color: #121212;
    color: #e0e0e0;
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
}

.chat-sidebar {
    width: 20%;
    min-width: 200px;
    max-width: 280px;
    flex-shrink: 0;
}

.chat-main {
    flex: 1;
    display: flex;
    flex-direction: column;
    min-width: 0;
    overflow: hidden;
}

.chat-main.expanded {
    /* When no thread is open, take remaining space */
}

.chat-thread {
    width: 25%;
    min-width: 280px;
    max-width: 400px;
    flex-shrink: 0;
}

.main-header {
    padding: 14px 20px;
    border-bottom: 1px solid #333;
    background: #1e1e1e;
}

.main-header h2 {
    margin: 0;
    font-size: 1.1rem;
    font-weight: 700;
    color: #fff;
}

.header-desc {
    font-size: 0.8rem;
    color: #9e9e9e;
    margin-top: 2px;
    display: block;
}

.message-scroll {
    flex: 1;
    overflow-y: auto;
    padding: 8px 0;
    display: flex;
    flex-direction: column;
}

.load-more-area {
    display: flex;
    justify-content: center;
    padding: 12px;
}

.load-more-btn {
    background: rgba(255, 255, 255, 0.08);
    border: 1px solid #444;
    color: #42a5f5;
    padding: 6px 16px;
    border-radius: 6px;
    font-size: 0.8rem;
    cursor: pointer;
    transition: background-color 0.15s;
}

.load-more-btn:hover:not(:disabled) {
    background: rgba(255, 255, 255, 0.12);
}

.load-more-btn:disabled {
    opacity: 0.5;
    cursor: default;
}

.empty-state {
    flex: 1;
    display: flex;
    align-items: center;
    justify-content: center;
}

.empty-state p {
    color: #757575;
    font-size: 1rem;
}

